/* consensustest comparison report — static UI.
 *
 * Reads window.REPORT_DATA (populated by data.js — regenerated by
 * `make stresstest`) and renders the page. Edit freely and
 * refresh the browser; no test rerun required.
 *
 * Page structure per sweep:
 *  Section: <sweep title>
 *    Part A — Cross-protocol comparison:
 *      one <details>-collapsible chart pack per Scenario.Group.
 *    Part B — OBFT-only scenarios (at the end):
 *      one collapsible pack per group containing scenarios where QBFT
 *      is ExpectNotApplicable.
 *
 *  Each pack contains: matrix (clickable rows) + ONE interactive chart
 *  showing the selected scenario's data:
 *    - 1-point sweep  → bar chart of P50/P90/P99 decision time.
 *    - multi-point    → line chart of P99 decision time vs swept axis.
 *
 *  The first pack of each sweep is open by default; the rest are
 *  collapsed to keep the page short. Scroll-driven IntersectionObserver
 *  highlights the active sweep in the sticky TOC and exposes a
 *  per-sweep sub-row of group anchors.
 */

'use strict';

// Protocol series colors — used for chart bars, lines, and point markers.
// Picked as a warm-toned pair with similar saturation/lightness so the
// two protocols read as peers, not as figure/ground. The UI accent
// (sticky TOC active state, focus ring, etc.) lives in styles.css and
// stays cool blue, independent of these.
const PROTOCOL_COLORS = {
  OBFT: '#ed8936', // light orange
  QBFT: '#e85a71', // light pink-red
};

// chartInstances tracks every Chart.js instance for debug/teardown.
// Per-pack inits are scheduled lazily — see scheduleChartInit() and
// renderGroupPack(); the cross-sweep panel runs its own init list
// inline (see openCrossSweepPanel).
const chartInstances = [];

// packsBySweep keeps track of the group packs in each sweep so the
// sub-TOC can rebuild its group anchors when the active sweep changes.
const packsBySweep = {};

document.addEventListener('DOMContentLoaded', main);

function main() {
  const data = window.REPORT_DATA;
  const root = document.getElementById('root');
  if (!data) {
    return; // index.html already shows the placeholder.
  }
  applyChartDefaults();
  const bucketing = computeBuckets(data);

  root.innerHTML = '';
  root.appendChild(renderHeader(data));
  root.appendChild(renderTOC(data));
  const mainEl = h('main');
  data.sweeps.forEach((sw) => mainEl.appendChild(renderSweepSection(sw, data, bucketing)));
  root.appendChild(mainEl);
  // Default-open packs init their charts immediately; collapsed packs
  // defer until their first toggle (see scheduleChartInit).
  document.querySelectorAll('details.group-pack[open]').forEach((d) => fireChartInit(d));
  setupActiveTOC(data);
  setupHashSync(data);
  setupTocHeightVar();
}

// setupTocHeightVar measures the sticky TOC's height and exposes it as
// `--toc-height` on <html>, so the per-pack sticky <summary> rules can
// land just below the TOC instead of overlapping it. Re-measures on
// resize and on sub-row rebuilds (different sweeps can wrap differently).
function setupTocHeightVar() {
  const nav = document.querySelector('nav.toc');
  if (!nav) return;
  const update = () => {
    const h = Math.ceil(nav.getBoundingClientRect().height);
    document.documentElement.style.setProperty('--toc-height', `${h}px`);
  };
  update();
  window.addEventListener('resize', update);
  // Anything inside the TOC that changes layout (sub-row rebuild when
  // the active sweep changes, etc.) — observe and react.
  const obs = new MutationObserver(update);
  obs.observe(nav, { childList: true, subtree: true, characterData: true });
}

// scheduleChartInit binds initFn to a pack, firing it on the pack's first
// open. If the pack is already open at registration time, it fires
// synchronously. Subsequent open/close events are no-ops.
function scheduleChartInit(details, initFn) {
  let fired = false;
  const fire = () => {
    if (fired) return;
    fired = true;
    const inst = initFn();
    if (inst) chartInstances.push(inst);
  };
  details._fireChartInit = fire;
  details.addEventListener('toggle', () => {
    if (details.hasAttribute('open')) fire();
  });
}

// fireChartInit triggers a pack's bound init (if any). Used by the main
// initial pass to render default-open packs, and by expand-all.
function fireChartInit(details) {
  if (details._fireChartInit) details._fireChartInit();
}

// applyChartDefaults tweaks Chart.js globally so individual chart
// configs stay short. Lighter gridlines, friendlier tooltips, rounded
// bars, the page's typography.
function applyChartDefaults() {
  if (typeof Chart === 'undefined') return;
  Chart.defaults.font.family = '-apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';
  Chart.defaults.font.size = 12;
  Chart.defaults.color = '#475569';
  Chart.defaults.borderColor = 'rgba(15, 23, 42, 0.06)';
  Chart.defaults.elements.bar.borderRadius = 4;
  Chart.defaults.elements.bar.borderWidth = 0;
  Chart.defaults.elements.line.tension = 0.15;
  Chart.defaults.elements.line.borderWidth = 2.5;
  Chart.defaults.elements.point.radius = 4;
  Chart.defaults.elements.point.hoverRadius = 7;
  Chart.defaults.plugins.tooltip.padding = 10;
  Chart.defaults.plugins.tooltip.cornerRadius = 6;
  Chart.defaults.plugins.tooltip.backgroundColor = 'rgba(15, 23, 42, 0.92)';
  Chart.defaults.plugins.tooltip.titleFont = { size: 12, weight: '600' };
  Chart.defaults.plugins.tooltip.bodyFont = { size: 12 };
  Chart.defaults.plugins.tooltip.boxPadding = 6;
  Chart.defaults.plugins.legend.labels.boxWidth = 12;
  Chart.defaults.plugins.legend.labels.font = { size: 12 };
}

// ---- scope + group bucketing -----------------------------------------

// computeBuckets partitions scenarios into "cross" (applies to every
// protocol in the data) and "obftOnly" (QBFT marked n/a everywhere).
// Within each scope, scenarios stay in Catalog order grouped by their
// Scenario.Group field, with first-appearance ordering of groups.
function computeBuckets(data) {
  const scopeByName = {};
  data.scenarios.forEach((sc) => {
    let hasQbft = false;
    outer: for (const sw of data.sweeps) {
      for (const pt of sw.points) {
        const cell = findCell(pt, sc.name, 'QBFT');
        if (cell && cell.iterations > 0) {
          hasQbft = true;
          break outer;
        }
      }
    }
    scopeByName[sc.name] = hasQbft ? 'cross' : 'obftOnly';
  });

  const buckets = { cross: {}, obftOnly: {} };
  const groupOrder = { cross: [], obftOnly: [] };
  data.scenarios.forEach((sc) => {
    const scope = scopeByName[sc.name];
    const group = sc.group || 'Other';
    if (!buckets[scope][group]) {
      buckets[scope][group] = [];
      groupOrder[scope].push(group);
    }
    buckets[scope][group].push(sc);
  });
  return { buckets, groupOrder };
}

// ---- top-level scaffolding -------------------------------------------

function renderHeader(data) {
  const header = h('header', { class: 'page', id: 'top' });
  // Single self-explanatory sentence covers everything: the count and
  // role of sweeps, the protocols being compared, and the per-cell
  // sample size (and what "cell" means). No separate title, lead, or
  // pills — those split the same content across more visual chrome
  // than it deserves.
  const meta = h('p', { class: 'meta-line' });
  meta.innerHTML =
    `<strong>${data.sweeps.length} parameter sweeps</strong>` +
    ` comparing <strong>${escapeHtml(data.protocols.join(' vs '))}</strong>` +
    ` — each <strong>(scenario, protocol) pair</strong>` +
    ` simulated <strong>${data.iterations} times</strong>`;
  header.appendChild(meta);

  // Expand-all / collapse-all controls.
  const controls = h('div', { class: 'header-controls' });
  const expandBtn = h('button', { type: 'button', 'data-action': 'expand-all' }, 'Expand all');
  const collapseBtn = h('button', { type: 'button', 'data-action': 'collapse-all' }, 'Collapse all');
  expandBtn.addEventListener('click', () => toggleAllPacks(true));
  collapseBtn.addEventListener('click', () => toggleAllPacks(false));
  controls.appendChild(expandBtn);
  controls.appendChild(collapseBtn);
  header.appendChild(controls);
  return header;
}

// toggleAllPacks opens or closes every <details.group-pack> on the page.
// Setting/removing the `open` attribute fires the `toggle` event, which
// the lazy-init wiring picks up.
function toggleAllPacks(open) {
  document.querySelectorAll('details.group-pack').forEach((d) => {
    if (open && !d.hasAttribute('open')) {
      d.setAttribute('open', '');
      fireChartInit(d);
    } else if (!open && d.hasAttribute('open')) {
      d.removeAttribute('open');
    }
  });
}

// renderTOC builds the sticky nav with two rows:
//   1. Sweep row — one pill per sweep; active sweep highlighted.
//   2. Sub-row   — group anchors for the active sweep, rebuilt on
//                  scroll. A small `OBFT-only:` divider separates
//                  the cross-protocol anchors (left) from the
//                  OBFT-only anchors (right) so the symmetry of
//                  group names across scopes reads clearly.
function renderTOC(data) {
  const nav = h('nav', { class: 'toc' });

  const sweepRow = h('div', { class: 'toc-row sweeps' });
  data.sweeps.forEach((sw) => {
    sweepRow.appendChild(
      h('a', { href: `#sweep-${sw.name}`, 'data-sweep': sw.name }, sw.title || sw.name),
    );
  });
  nav.appendChild(sweepRow);

  nav.appendChild(h('div', { class: 'toc-row groups', 'data-active-sweep': '' }));

  return nav;
}

function renderSweepSection(sweep, data, bucketing) {
  const section = h('section', { class: 'sweep', id: `sweep-${sweep.name}` });
  const head = h('div', { class: 'sweep-head' });
  head.appendChild(h('h2', {}, sweep.title || sweep.name));
  if (sweep.description) {
    const desc = h('p', { class: 'desc' });
    desc.innerHTML = formatDescription(sweep.description);
    head.appendChild(desc);
  }
  section.appendChild(head);

  packsBySweep[sweep.name] = [];
  renderScope(section, sweep, data, bucketing, 'cross', 'Cross-protocol comparison', data.protocols);
  renderScope(section, sweep, data, bucketing, 'obftOnly', 'OBFT-only scenarios', ['OBFT']);

  return section;
}

function renderScope(section, sweep, data, bucketing, scopeKey, scopeLabel, protocols) {
  const groups = bucketing.groupOrder[scopeKey];
  if (groups.length === 0) return;
  const isObftOnly = scopeKey === 'obftOnly';
  section.appendChild(
    h(
      'div',
      { class: `scope-heading ${isObftOnly ? 'obft-only' : 'cross'}` },
      scopeLabel,
    ),
  );
  groups.forEach((group, idx) => {
    const scenarios = bucketing.buckets[scopeKey][group];
    // Default-open the very first pack of each sweep (Cross-protocol
    // Baseline); everything else starts collapsed for a calmer page.
    const open = scopeKey === 'cross' && idx === 0;
    renderGroupPack(section, sweep, scopeKey, group, scenarios, protocols, open);
  });
}

function renderGroupPack(section, sweep, scopeKey, group, scenarios, protocols, open) {
  const packID = `${sweep.name}_${scopeKey}_${slugify(group)}`;
  const isTrend = sweep.points.length > 1;
  const details = h('details', {
    class: `group-pack ${isTrend ? 'trend' : 'detail'} ${scopeKey === 'obftOnly' ? 'obft-only' : ''}`,
    id: `pack-${packID}`,
  });
  if (open) details.setAttribute('open', '');

  const summary = h('summary');
  summary.appendChild(h('span', { class: 'group-name' }, group));
  summary.appendChild(
    h('span', { class: 'group-count' }, `${scenarios.length} scenario${scenarios.length !== 1 ? 's' : ''}`),
  );
  details.appendChild(summary);

  const body = h('div', { class: `group-body ${isTrend ? 'trend' : 'detail'}` });
  // renderGroup* returns the init function so we can defer Chart.js
  // construction until the pack first opens. The matrix is built
  // eagerly so it shows in the summary view if the user hovers etc.
  const initFn = isTrend
    ? renderGroupTrend(body, sweep, scenarios, protocols, packID)
    : renderGroupDetail(body, sweep, scenarios, protocols, packID);
  details.appendChild(body);

  scheduleChartInit(details, initFn);
  section.appendChild(details);
  packsBySweep[sweep.name].push({ id: `pack-${packID}`, label: group, scope: scopeKey });
}

// ---- detail layout (1-point sweep) -----------------------------------
//
// Each group renders ONE interactive chart driven by the matrix:
//   - Summary matrix with clickable rows; first row selected by default.
//   - Bar chart below shows decision-time P50/P90/P99 (in ms) for the
//     selected scenario, with one bar group per protocol.
// Success rate is NOT redrawn in chart form — it's already in the matrix.

function renderGroupDetail(section, sweep, scenarios, protocols, packID) {
  const point = sweep.points[0];
  const initial = scenarios[0];

  const table = renderSummaryMatrix(point, scenarios, protocols);
  section.appendChild(table);

  const wrap = h('div', { class: 'chart-wrap' });
  const canvas = h('canvas', { id: `${packID}_chart` });
  wrap.appendChild(canvas);
  section.appendChild(wrap);

  // Returned so the pack can defer Chart.js init until first open.
  return () => {
    const chart = buildLatencyChart(canvas, point, protocols, initial);
    wireMatrixSelection(table, scenarios, initial, (sc) => {
      updateLatencyChart(chart, point, protocols, sc);
    });
    return chart;
  };
}

// renderCell renders one numeric matrix cell with three right-aligned
// spans (success% · "P99 Xms" · bandwidth median) so columns line up
// across rows. A miss reason (if any) shows as a small line below.
function renderCell(cell) {
  if (!cell || cell.iterations === 0) {
    return h('td', { class: 'na' }, 'n/a');
  }
  let cls = 'ok';
  if (cell.successRate < 0.5) cls = 'miss';
  else if (cell.successRate < 1.0) cls = 'warn';
  const p99 = cell.decisionTime ? Math.round(cell.decisionTime.p99) : 0;
  const bw = cell.clusterBandwidth ? cell.clusterBandwidth.p50 : null;
  const td = h(
    'td',
    { class: cls },
    h('span', { class: 'pct' }, `${Math.round(cell.successRate * 100)}%`),
    h('span', { class: 'lat' }, `P99 ${p99} ms`),
    h('span', { class: 'bw' }, formatBytes(bw)),
  );
  const reason = topMissReason(cell);
  if (reason) {
    td.appendChild(h('div', { class: 'miss-reason' }, reason));
  }
  return td;
}

// formatBytes returns a compact byte string: 16356 → "16 KB", 1234567 → "1.2 MB".
function formatBytes(n) {
  if (n == null || isNaN(n) || n <= 0) return '—';
  if (n < 1024) return `${Math.round(n)} B`;
  if (n < 1024 * 1024) return `${Math.round(n / 1024)} KB`;
  return `${(n / (1024 * 1024)).toFixed(1)} MB`;
}

// topMissReason returns the most-common miss-reason label for a cell,
// or null if the cell didn't miss or no reasons were reported.
function topMissReason(cell) {
  if (!cell || !cell.missReasons) return null;
  let top = null;
  let topN = 0;
  Object.entries(cell.missReasons).forEach(([k, n]) => {
    if (n > topN) {
      top = k;
      topN = n;
    }
  });
  return top;
}

function renderSummaryMatrix(point, scenarios, protocols) {
  const table = h('table', { class: 'matrix' });
  // Empty leftmost header: the row's scenario name is self-labelling and
  // the column needs no caption. The OBFT / QBFT headers still anchor
  // their data columns.
  const headerRow = h('tr', {}, h('th', {}));
  protocols.forEach((p) => headerRow.appendChild(h('th', {}, p)));
  table.appendChild(h('thead', {}, headerRow));

  const tbody = h('tbody');
  scenarios.forEach((sc) => {
    const row = h(
      'tr',
      { 'data-scenario': sc.name },
      renderScenarioCell(sc),
    );
    protocols.forEach((p) => row.appendChild(renderCell(findCell(point, sc.name, p))));
    tbody.appendChild(row);
  });
  table.appendChild(tbody);
  return table;
}

// renderScenarioCell builds the leftmost cell of a matrix row: scenario
// title plus a small "↗ all sweeps" button that opens the cross-sweep
// panel for that scenario.
function renderScenarioCell(sc) {
  const td = h('td', { class: 'scen' });
  td.appendChild(h('span', { class: 'scen-title' }, sc.title));
  const btn = h(
    'button',
    {
      type: 'button',
      class: 'cross-sweep-btn',
      'aria-label': `View ${sc.title} across all sweeps`,
      title: 'View this scenario across all sweeps',
    },
    '↗',
  );
  btn.addEventListener('click', (ev) => {
    ev.stopPropagation(); // don't trigger row selection
    openCrossSweepPanel(sc);
  });
  td.appendChild(btn);
  return td;
}

function buildLatencyChart(canvas, point, protocols, scenario) {
  return new Chart(canvas, {
    type: 'bar',
    data: latencyChartData(point, protocols, scenario),
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        y: {
          title: { display: true, text: 'decision time (ms)' },
          grid: { color: 'rgba(15, 23, 42, 0.06)' },
          ticks: { padding: 6 },
        },
        x: {
          title: { display: false },
          grid: { display: false },
          ticks: { padding: 4 },
        },
      },
      plugins: {
        legend: { position: 'top', align: 'end' },
        tooltip: {
          callbacks: {
            title: (items) => items[0] ? items[0].label : '',
            label: (ctx) => `${ctx.dataset.label}: ${Math.round(ctx.parsed.y)} ms`,
          },
        },
      },
    },
  });
}

// SLOT_END_MS is the canonical relay cutoff (the spec's 4s proposer-duty
// deadline). Used as the synthetic bar height for "no decision" runs:
// a protocol that ran iterations but never decided consumed the full
// slot budget, so a full-height grey bar communicates that visually
// instead of silently dropping the dataset.
const SLOT_END_MS = 4000;
const NO_DECISION_COLOR = 'rgba(148, 163, 184, 0.55)';
const NO_DECISION_BORDER = 'rgba(100, 116, 139, 0.85)';

function latencyChartData(point, protocols, scenario) {
  return {
    labels: ['P50', 'P90', 'P99'],
    datasets: protocols.map((p) => {
      const cell = findCell(point, scenario.name, p);
      if (cell && cell.decisionTime) {
        return {
          label: p,
          backgroundColor: protocolColor(p),
          borderColor: protocolColor(p),
          data: [cell.decisionTime.p50, cell.decisionTime.p90, cell.decisionTime.p99],
        };
      }
      // Ran iterations but never decided → render a grey bar at the
      // slot-end deadline so the failure is visually present (instead
      // of an unexplained gap where the protocol's bars would be).
      if (cell && cell.iterations > 0) {
        return {
          label: `${p} (no decision)`,
          backgroundColor: NO_DECISION_COLOR,
          borderColor: NO_DECISION_BORDER,
          borderWidth: 1,
          data: [SLOT_END_MS, SLOT_END_MS, SLOT_END_MS],
        };
      }
      // Scenario is n/a for this protocol (no iterations ran).
      return {
        label: p,
        backgroundColor: protocolColor(p),
        borderColor: protocolColor(p),
        data: [null, null, null],
      };
    }),
  };
}

function updateLatencyChart(chart, point, protocols, scenario) {
  const d = latencyChartData(point, protocols, scenario);
  chart.data.labels = d.labels;
  chart.data.datasets = d.datasets;
  chart.options.plugins.title.text = scenario.title;
  chart.update();
}

// ---- trend layout (multi-point sweep) --------------------------------
//
// Each group renders ONE interactive line chart driven by a per-axis
// matrix. The chart plots P99 decision time vs swept axis for the
// selected scenario, with one line per protocol.

function renderGroupTrend(section, sweep, scenarios, protocols, packID) {
  const initial = scenarios[0];

  const table = renderTrendMatrix(sweep, scenarios, protocols);
  section.appendChild(table);

  const wrap = h('div', { class: 'chart-wrap' });
  const canvas = h('canvas', { id: `${packID}_chart` });
  wrap.appendChild(canvas);
  section.appendChild(wrap);

  return () => {
    const chart = buildTrendLineChart(canvas, sweep, protocols, initial);
    wireMatrixSelection(table, scenarios, initial, (sc) => {
      updateTrendLineChart(chart, sweep, protocols, sc);
    });
    return chart;
  };
}

function renderTrendMatrix(sweep, scenarios, protocols) {
  const table = h('table', { class: 'matrix trend' });
  // Empty leftmost header (scenario name is self-labelling) — matches
  // the detail-matrix convention.
  const headerRow = h('tr', {}, h('th', {}));
  sweep.points.forEach((pt) => headerRow.appendChild(h('th', {}, pt.label)));
  table.appendChild(h('thead', {}, headerRow));

  const tbody = h('tbody');
  scenarios.forEach((sc) => {
    const row = h('tr', { 'data-scenario': sc.name }, renderScenarioCell(sc));
    sweep.points.forEach((pt) => {
      const td = h('td', { class: 'point' });
      protocols.forEach((p) => {
        const cell = findCell(pt, sc.name, p);
        const line = h('div', { class: 'cell-line' });
        line.appendChild(h('span', { class: 'proto' }, `${p}:`));
        if (!cell || cell.iterations === 0) {
          line.classList.add('na');
          line.appendChild(h('span', { class: 'pct' }, 'n/a'));
        } else {
          let cls = 'ok';
          if (cell.successRate < 0.5) cls = 'miss';
          else if (cell.successRate < 1.0) cls = 'warn';
          line.classList.add(cls);
          const p99 = cell.decisionTime ? Math.round(cell.decisionTime.p99) : 0;
          const bw = cell.clusterBandwidth ? cell.clusterBandwidth.p50 : null;
          line.appendChild(h('span', { class: 'pct' }, `${Math.round(cell.successRate * 100)}%`));
          line.appendChild(h('span', { class: 'lat' }, `${p99} ms`));
          line.appendChild(h('span', { class: 'bw' }, formatBytes(bw)));
          const reason = topMissReason(cell);
          if (reason) line.title = `Top miss reason: ${reason}`;
        }
        td.appendChild(line);
      });
      row.appendChild(td);
    });
    tbody.appendChild(row);
  });
  table.appendChild(tbody);
  return table;
}

function buildTrendLineChart(canvas, sweep, protocols, scenario) {
  return new Chart(canvas, {
    type: 'line',
    data: trendLineChartData(sweep, protocols, scenario),
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'nearest', intersect: false },
      scales: {
        x: {
          title: { display: true, text: sweep.axisLabel || '' },
          grid: { display: false },
          ticks: { padding: 4 },
        },
        y: {
          title: { display: true, text: 'P99 decision time (ms)' },
          grid: { color: 'rgba(15, 23, 42, 0.06)' },
          ticks: { padding: 6 },
        },
      },
      plugins: {
        legend: { position: 'top', align: 'end' },
        tooltip: {
          callbacks: {
            title: (items) => (items[0] ? `${sweep.axisLabel || 'point'}: ${items[0].label}` : ''),
            label: (ctx) => `${ctx.dataset.label}: P99 ${Math.round(ctx.parsed.y)} ms`,
          },
        },
      },
    },
  });
}

function trendLineChartData(sweep, protocols, scenario) {
  return {
    labels: sweep.points.map((pt) => pt.label),
    datasets: protocols.map((p) => {
      const data = sweep.points.map((pt) => {
        const cell = findCell(pt, scenario.name, p);
        if (!cell || cell.iterations === 0 || !cell.decisionTime) return null;
        return cell.decisionTime.p99;
      });
      return {
        label: p,
        borderColor: protocolColor(p),
        backgroundColor: protocolColor(p),
        pointStyle: protocolPointStyle(p),
        spanGaps: true,
        fill: false,
        tension: 0.15,
        borderDash: protocolDash(p),
        data,
      };
    }),
  };
}

function updateTrendLineChart(chart, sweep, protocols, scenario) {
  const d = trendLineChartData(sweep, protocols, scenario);
  chart.data.labels = d.labels;
  chart.data.datasets = d.datasets;
  chart.options.plugins.title.text = scenario.title;
  chart.update();
}

// ---- shared: matrix → chart wiring -----------------------------------

// wireMatrixSelection adds click + keyboard handlers to every <tbody>
// row in `table`. Click selects; ArrowUp/ArrowDown move the selection
// to the previous/next row. The row for `initial` starts pre-selected
// and tabbable.
function wireMatrixSelection(table, scenarios, initial, onSelect) {
  const byName = new Map();
  scenarios.forEach((sc) => byName.set(sc.name, sc));
  const rows = Array.from(table.querySelectorAll('tbody tr'));

  const select = (row) => {
    const sname = row.getAttribute('data-scenario');
    const sc = byName.get(sname);
    if (!sc) return;
    rows.forEach((r) => {
      r.classList.remove('selected');
      r.setAttribute('tabindex', '-1');
    });
    row.classList.add('selected');
    row.setAttribute('tabindex', '0');
    onSelect(sc);
  };

  rows.forEach((row) => {
    const sname = row.getAttribute('data-scenario');
    row.setAttribute('tabindex', sname === initial.name ? '0' : '-1');
    row.setAttribute('role', 'button');
    if (sname === initial.name) row.classList.add('selected');
    row.addEventListener('click', () => select(row));
    row.addEventListener('keydown', (ev) => {
      if (ev.key !== 'ArrowDown' && ev.key !== 'ArrowUp') return;
      ev.preventDefault();
      const dir = ev.key === 'ArrowDown' ? 1 : -1;
      const idx = rows.indexOf(row);
      const next = rows[(idx + dir + rows.length) % rows.length];
      if (next) {
        select(next);
        next.focus();
      }
    });
  });
}

// ---- helpers ---------------------------------------------------------

// h(tag, attrs, ...children) — small DOM builder. attrs are setAttribute'd
// (except 'class', which sets className). Children may be strings (wrapped
// as text nodes), DOM nodes, or null/undefined (skipped).
function h(tag, attrs, ...children) {
  const el = document.createElement(tag);
  if (attrs) {
    Object.entries(attrs).forEach(([k, v]) => {
      if (k === 'class') el.className = v;
      else el.setAttribute(k, v);
    });
  }
  children.flat().forEach((c) => {
    if (c == null) return;
    if (typeof c === 'string' || typeof c === 'number') {
      el.appendChild(document.createTextNode(String(c)));
    } else {
      el.appendChild(c);
    }
  });
  return el;
}

// findCell — linear scan; fine at the matrix sizes the framework targets.
function findCell(point, scenarioName, protocolName) {
  return point.cells.find((c) => c.scenario === scenarioName && c.protocol === protocolName) || null;
}

function protocolColor(name) {
  return PROTOCOL_COLORS[name] || '#888';
}

function protocolDash(name) {
  return name === 'OBFT' ? [] : [6, 4];
}

function protocolPointStyle(name) {
  switch (name) {
    case 'OBFT':
      return 'circle';
    case 'QBFT':
      return 'triangle';
    default:
      return 'rect';
  }
}

// slugify converts a human-readable group label to a DOM-safe slug.
// Used to build canvas IDs like `canonical_cross_silent_operators_success`.
function slugify(s) {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

// setupActiveTOC wires the sticky nav's two rows to scroll position via
// a scroll listener (IntersectionObserver was less reliable in headless
// preview environments — sticking with the simpler approach):
//   - Top row: highlight the sweep section whose top is just above the
//     viewport's 25%-from-top probe point.
//   - Sub-row: rebuild on every active-sweep change to list that sweep's
//     group anchors; highlight the pack whose top is similarly near the
//     probe.
function setupActiveTOC(data) {
  const sweepLinks = new Map();
  document.querySelectorAll('nav.toc .toc-row.sweeps a[data-sweep]').forEach((a) => {
    sweepLinks.set(a.getAttribute('data-sweep'), a);
  });
  const subRow = document.querySelector('nav.toc .toc-row.groups');
  if (!subRow || sweepLinks.size === 0) return;

  let activeSweep = data.sweeps[0]?.name;
  let activePack = null;

  const rebuildSubRow = (sweepName) => {
    subRow.innerHTML = '';
    subRow.setAttribute('data-active-sweep', sweepName);
    let dividerInserted = false;
    (packsBySweep[sweepName] || []).forEach((pack) => {
      // First time we hit an OBFT-only pack, drop in a visual divider
      // so the cross-protocol vs OBFT-only split is unmistakable.
      if (pack.scope === 'obftOnly' && !dividerInserted) {
        subRow.appendChild(h('span', { class: 'scope-divider' }, 'OBFT-only:'));
        dividerInserted = true;
      }
      subRow.appendChild(
        h(
          'a',
          { href: `#${pack.id}`, class: pack.scope === 'obftOnly' ? 'obft-only' : 'cross' },
          pack.label,
        ),
      );
    });
    if (activePack) markPackActive(activePack);
  };
  const markSweepActive = (name) => {
    if (activeSweep === name) return;
    activeSweep = name;
    sweepLinks.forEach((a, n) => a.classList.toggle('active', n === name));
    rebuildSubRow(name);
  };
  const markPackActive = (id) => {
    activePack = id;
    subRow.querySelectorAll('a').forEach((a) => {
      a.classList.toggle('active', a.getAttribute('href') === `#${id}`);
    });
  };

  // Initial render.
  rebuildSubRow(activeSweep);
  sweepLinks.get(activeSweep)?.classList.add('active');

  // Probe is at 25% of viewport height from the top — far enough below
  // the sticky TOC that "what section am I reading" maps to the section
  // whose top is at-or-above the probe.
  const detectActive = () => {
    const probeY = window.scrollY + window.innerHeight * 0.25;
    const sections = document.querySelectorAll('section.sweep');
    let active = sections[0];
    sections.forEach((s) => {
      if (s.offsetTop <= probeY) active = s;
    });
    if (active) markSweepActive(active.id.replace(/^sweep-/, ''));

    const packs = document.querySelectorAll('details.group-pack');
    let activeP = null;
    packs.forEach((p) => {
      if (p.offsetTop <= probeY) activeP = p;
    });
    if (activeP) markPackActive(activeP.id);
  };

  let scrollPending = false;
  const onScroll = () => {
    if (scrollPending) return;
    scrollPending = true;
    setTimeout(() => {
      scrollPending = false;
      detectActive();
    }, 60);
  };
  window.addEventListener('scroll', onScroll, { passive: true });
  // Also run once after initial layout in case the page loaded scrolled.
  detectActive();
}

// ---- cross-sweep panel ------------------------------------------------
//
// openCrossSweepPanel shows the selected scenario's behaviour across
// every sweep in a modal <dialog>. Each sweep renders as a compact
// section: a one-line summary plus a mini Chart.js chart (bar for
// single-point sweeps, line for multi-point sweeps).

function openCrossSweepPanel(scenario) {
  const data = window.REPORT_DATA;
  if (!data) return;

  // Cache one <dialog> element across opens to avoid leaking listeners.
  let dlg = document.getElementById('cross-sweep-dialog');
  if (!dlg) {
    dlg = h('dialog', { id: 'cross-sweep-dialog', class: 'cross-sweep' });
    document.body.appendChild(dlg);
    dlg.addEventListener('click', (ev) => {
      if (ev.target === dlg) dlg.close(); // backdrop click closes
    });
  }
  dlg.innerHTML = '';

  // Header.
  const head = h('header', { class: 'cs-head' });
  head.appendChild(h('h2', {}, scenario.title));
  head.appendChild(h('p', { class: 'cs-meta' }, `Scenario: ${scenario.name} · group: ${scenario.group || 'Other'}`));
  const closeBtn = h('button', { type: 'button', class: 'cs-close', 'aria-label': 'Close' }, '×');
  closeBtn.addEventListener('click', () => dlg.close());
  head.appendChild(closeBtn);
  dlg.appendChild(head);

  // One section per sweep.
  const body = h('div', { class: 'cs-body' });
  const inits = [];
  data.sweeps.forEach((sw, swIdx) => {
    const sec = h('section', { class: 'cs-sweep' });
    sec.appendChild(h('h3', {}, sw.title || sw.name));
    if (sw.axisLabel) sec.appendChild(h('p', { class: 'cs-axis' }, `Swept axis: ${sw.axisLabel}`));

    // Summary line: applicable to which protocols? Mean P99 if any.
    sec.appendChild(buildCrossSweepSummary(sw, scenario, data.protocols));

    // Chart.
    const wrap = h('div', { class: 'cs-chart-wrap' });
    const canvas = h('canvas', { id: `cs_${swIdx}_${slugify(scenario.name)}` });
    wrap.appendChild(canvas);
    sec.appendChild(wrap);
    inits.push(() => buildCrossSweepChart(canvas, sw, scenario, data.protocols));

    body.appendChild(sec);
  });
  dlg.appendChild(body);

  dlg.showModal();
  // Init charts after the dialog is in the DOM and visible so canvases
  // have measurable dimensions.
  inits.forEach((fn) => {
    const inst = fn();
    if (inst) chartInstances.push(inst);
  });
}

function buildCrossSweepSummary(sw, scenario, protocols) {
  // Collect cells for this scenario across every point in the sweep.
  // Report: "OBFT: success% range, P99 range · QBFT: ..." (or "n/a" for
  // protocols where every cell is unapplicable).
  const parts = h('p', { class: 'cs-summary' });
  protocols.forEach((p, i) => {
    if (i > 0) parts.appendChild(h('span', { class: 'cs-sep' }, ' · '));
    const cells = sw.points
      .map((pt) => findCell(pt, scenario.name, p))
      .filter((c) => c && c.iterations > 0);
    const span = h('span', { class: `cs-proto cs-${p.toLowerCase()}` });
    span.appendChild(h('strong', {}, `${p}:`));
    if (cells.length === 0) {
      span.appendChild(h('span', { class: 'na' }, ' n/a'));
    } else {
      const successes = cells.map((c) => c.successRate);
      const p99s = cells.map((c) => (c.decisionTime ? c.decisionTime.p99 : null)).filter((v) => v !== null);
      const sMin = Math.round(Math.min(...successes) * 100);
      const sMax = Math.round(Math.max(...successes) * 100);
      const sStr = sMin === sMax ? `${sMin}%` : `${sMin}–${sMax}%`;
      let pStr = '—';
      if (p99s.length > 0) {
        const pMin = Math.round(Math.min(...p99s));
        const pMax = Math.round(Math.max(...p99s));
        pStr = pMin === pMax ? `P99 ${pMin} ms` : `P99 ${pMin}–${pMax} ms`;
      }
      span.appendChild(h('span', {}, ` ${sStr} · ${pStr}`));
    }
    parts.appendChild(span);
  });
  return parts;
}

function buildCrossSweepChart(canvas, sw, scenario, protocols) {
  if (sw.points.length === 1) {
    // Single point → bar chart of P50/P90/P99.
    return buildLatencyChart(canvas, sw.points[0], protocols, scenario);
  }
  // Multi-point → line chart of P99 across the swept axis.
  return buildTrendLineChart(canvas, sw, protocols, scenario);
}

// setupHashSync handles deep-linking into the report:
//   - On page load (and every hashchange), if location.hash points to a
//     pack, open it and run focusPackIntoView.
//   - Direct click handler on every nav.toc anchor so repeat clicks on
//     the SAME anchor (hashchange won't fire then) still re-focus the
//     target pack.
function setupHashSync(data) {
  const goto = (hash) => {
    if (!hash) return;
    const el = document.getElementById(hash);
    if (!el) return;
    let pack = el.closest && el.closest('details.group-pack');
    if (!pack && el.tagName === 'DETAILS') pack = el;
    if (pack && !pack.hasAttribute('open')) {
      pack.setAttribute('open', '');
      fireChartInit(pack);
    }
    // Layout has to settle after opening before we measure heights to
    // place the chart in view. Two rAFs is enough in real browsers; a
    // small setTimeout works around rAF throttling in headless preview.
    setTimeout(() => focusPackIntoView(el, pack), 80);
  };
  window.addEventListener('hashchange', () => goto((location.hash || '').slice(1)));
  // Event-delegated click handler — catches clicks on the sub-row
  // anchors too, which are rebuilt dynamically per active sweep.
  const nav = document.querySelector('nav.toc');
  if (nav) {
    nav.addEventListener('click', (ev) => {
      const a = ev.target.closest('a[href^="#"]');
      if (!a || !nav.contains(a)) return;
      const href = a.getAttribute('href');
      if (!href) return;
      // Always handle ourselves so repeat clicks (same hash, no
      // hashchange) still re-focus. preventDefault stops the browser's
      // native jump, which would race with our measure-then-scroll.
      ev.preventDefault();
      const hash = href.slice(1);
      if (location.hash !== '#' + hash) {
        history.replaceState(null, '', '#' + hash);
      }
      goto(hash);
    });
  }
  if (location.hash) goto(location.hash.slice(1));
}

// focusPackIntoView scrolls so the pack's summary sits just below the
// sticky TOC AND, if possible, the chart fits inside the viewport. If
// the pack is taller than the viewport (long matrix), we scroll past
// the matrix top to keep the chart-bottom visible — the sticky summary
// keeps "what group" anchored anyway.
function focusPackIntoView(el, pack) {
  const tocH =
    parseFloat(
      getComputedStyle(document.documentElement).getPropertyValue('--toc-height'),
    ) || 110;
  const viewportH = window.innerHeight;
  const docTop = (rect) => rect.top + window.scrollY;

  const elRect = el.getBoundingClientRect();
  // Default: pack top sits 8px below the sticky TOC.
  let targetY = docTop(elRect) - tocH - 8;

  if (pack) {
    const chart = pack.querySelector('.chart-wrap');
    if (chart) {
      const cRect = chart.getBoundingClientRect();
      const chartBottom = docTop(cRect) + cRect.height;
      // If chart-bottom would land below viewport-bottom at our default
      // target, push scroll down (= more) so chart-bottom sits ~24px
      // above viewport-bottom. The sticky summary keeps the title
      // visible even when this pushes matrix-top off the top.
      const visibleBottom = targetY + viewportH - 24;
      if (chartBottom > visibleBottom) {
        targetY += chartBottom - visibleBottom;
      }
    }
  }
  window.scrollTo({ top: Math.max(0, targetY), behavior: 'auto' });
}

// escapeHtml escapes the five HTML special chars. Used before injecting
// strings into innerHTML so user-controlled text (descriptions etc.)
// can't smuggle in markup.
function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (ch) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  })[ch]);
}

// formatDescription HTML-escapes the input, then wraps three families
// of tokens in <strong> for visual emphasis:
//
//   1. Set literals like `{4, 7, 10, 13}` or `{0.1, 0.3, 0.5, 0.7}`.
//   2. Parameter assignments like `n=4`, `BTT=200ms`, `Sigma=0.30`,
//      `LossRate=0.10`, `BurstFactor=5`, `Median=BTT/2`, `K=4`.
//   3. Known network-model names: ConstantDelay / LogNormalDelay /
//      LossyNetwork / PerReceiverDelay / CorrelatedLinkDelay /
//      JitteredDelay. These name the operating-point's network shape
//      and deserve to stand out.
//
// The result is an HTML fragment suitable for innerHTML.
function formatDescription(text) {
  const networkModels = '(?:ConstantDelay|LogNormalDelay|LossyNetwork|PerReceiverDelay|CorrelatedLinkDelay|JitteredDelay)';
  let out = escapeHtml(text);
  // Order matters: set literals first (they may contain '=') ... actually
  // sets don't contain '=', so order is fine either way. Bold each family
  // in turn with a unique pattern.
  const patterns = [
    /\{[^}]+\}/g, // sets like {4, 7, 10, 13}
    /\b[A-Za-z][A-Za-z_0-9]*=[A-Za-z0-9./_]+(?:ms|s)?\b/g, // param=value
    new RegExp('\\b' + networkModels + '\\b', 'g'), // network model names
  ];
  patterns.forEach((re) => {
    out = out.replace(re, (m) => `<strong>${m}</strong>`);
  });
  return out;
}
